mapper.select:

where visitor_id = #{visitorId}
  and del_flag = '0'
order by create_time desc

select count(1) from visitor_application
where visitor_id = #{visitorId}
  and status = '2'
  and del_flag = '0'
  and approve_time is not null
  and approve_time >= #{todayStart}
  and approve_time < #{nextDayStart}

select count(1) from visitor_application
where visitor_id = #{visitorId} and status = '0'
  and del_flag = '0'
  and start_time <= #{now}
  and end_time >= #{now}

mapper.update:
update visitor_application
set status = #{status}, approve_time = #{approveTime}, update_time = #{updateTime}
where application_id = #{applicationId} and status = '0' and del_flag = '0'

update visitor_application
set del_flag = '1', update_time = #{updateTime}
where application_id = #{applicationId} and visitor_id = #{visitorId}
  and status = '0' and del_flag = '0'
